// The developer tools' tab registry - ONE table that says what a tab is.                                                                                                                                                                                      
//                                                                                                                                                                                                                                                             
// Before this module the same fact was written down four times: a source                                                                                                                                                                                      
// table (jsonSources / xmlSources / textSources), a hand-maintained list                                                                                                                                                                                      
// of the tabs that had their own branch in renderTab, the scan list of                                                                                                                                                                                        
// the cross-tab search, and the hand-written section list of the export.                                                                                                                                                                                      
// They drifted, exactly as that arrangement invites: the search never                                                                                                                                                                                         
// looked at the Model Diff or the picked control, and the export's                                                                                                                                                                                            
// section titles ("ROUNDTRIP HISTORY") named tabs that do not exist, so                                                                                                                                                                                       
// its own truncation hint pointed at nothing.                                                                                                                                                                                                                 
//                                                                                                                                                                                                                                                             
// Now every consumer reads this table:                                                                                                                                                                                                                        
//                                                                                                                                                                                                                                                             
//   the dialog   which sub-views a group offers, and what to render                                                                                                                                                                                           
//   the search   every searchable tab, evaluated the way it renders                                                                                                                                                                                           
//   the export   every exported tab, in exportOrder                                                                                                                                                                                                           
//                                                                                                                                                                                                                                                             
// Adding a tab is one entry here. Nothing else has to be touched.                                                                                                                                                                                             
//                                                                                                                                                                                                                                                             
// The tab KEYS are a compatibility surface and deliberately unchanged:                                                                                                                                                                                        
// "?z2ui5-devtools=HISTORY" and the remembered last tab in                                                                                                                                                                                                    
// sessionStorage both store them, and a key that stopped resolving would                                                                                                                                                                                      
// silently reopen on the default tab. What changed is only how they are                                                                                                                                                                                       
// GROUPED for display.                                                                                                                                                                                                                                        
sap.ui.define(                                                                                                                                                                                                                                                 
  [                                                                                                                                                                                                                                                            
    "z2ui5/core/AppState",                                                                                                                                                                                                                                     
    "z2ui5/core/ViewSlots",                                                                                                                                                                                                                                    
    "z2ui5/devtools/Format",                                                                                                                                                                                                                                   
    "z2ui5/devtools/Inspect",                                                                                                                                                                                                                                  
    "z2ui5/devtools/Picker",                                                                                                                                                                                                                                   
    "z2ui5/devtools/Recorder",                                                                                                                                                                                                                                 
  ],                                                                                                                                                                                                                                                           
  (AppState, ViewSlots, Format, Inspect, Picker, Recorder) => {                                                                                                                                                                                                
    "use strict";                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
    // Slot readers - the developer tools' view onto ViewSlots                                                                                                                                                                                                 
    // ------------------------------------------------------------------                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    function getModelJson(view) {                                                                                                                                                                                                                              
      const model = view?.getModel?.();                                                                                                                                                                                                                        
      return model?.getData?.();                                                                                                                                                                                                                               
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // A model tab is only worth offering when the slot's model carries                                                                                                                                                                                        
    // DATA - an app without bound attributes serves an empty object, and                                                                                                                                                                                      
    // omitting the sub-view says "nothing here" more clearly than                                                                                                                                                                                             
    // rendering {}.                                                                                                                                                                                                                                           
    function hasModelData(slotKey) {                                                                                                                                                                                                                           
      const data = getModelJson(ViewSlots.getView(slotKey));                                                                                                                                                                                                   
      return Boolean(data) && Object.keys(data).length > 0;                                                                                                                                                                                                    
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function getViewContent(view) {                                                                                                                                                                                                                            
      // Private member access (developer tools only): XMLView keeps the raw                                                                                                                                                                                   
      // XML string as a pseudo property in mProperties, but does not declare                                                                                                                                                                                  
      // it in its metadata - getProperty("viewContent") therefore throws and                                                                                                                                                                                  
      // would abort the whole tab selection. Read the plain object instead.                                                                                                                                                                                   
      return view?.mProperties?.viewContent;                                                                                                                                                                                                                   
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function getRenderedContent(view) {                                                                                                                                                                                                                        
      // Private member access (developer tools only): _xContent holds the                                                                                                                                                                                     
      // view XML after XML templating ran; there is no public equivalent.                                                                                                                                                                                     
      return view?._xContent?.outerHTML;                                                                                                                                                                                                                       
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The view XML a slot currently holds: the live view's own viewContent                                                                                                                                                                                    
    // when UI5 kept it, else the source ViewSlots recorded when the slot was                                                                                                                                                                                  
    // filled (a fragment or a `definition`-built view keeps none).                                                                                                                                                                                            
    //                                                                                                                                                                                                                                                         
    // Read from the SLOT, never from the last response: a slot lives and dies                                                                                                                                                                                 
    // by ViewSlots.setView/destroy, and both ways of tearing one down end up                                                                                                                                                                                  
    // there - the backend's ["VIEW_SLOTS","destroy",...] action and the                                                                                                                                                                                       
    // roundtrip-free frontend close (cs_event-popup_close / popover_close,                                                                                                                                                                                    
    // which the backend formats as that very same action). Scraping the last                                                                                                                                                                                  
    // response's display action instead made the frontend close look like a                                                                                                                                                                                   
    // popup that was still open: no roundtrip happens, so the response that                                                                                                                                                                                   
    // opened it stayed the current one.                                                                                                                                                                                                                       
    function getSlotXml(slotKey) {                                                                                                                                                                                                                             
      return (                                                                                                                                                                                                                                                 
        getViewContent(ViewSlots.getView(slotKey)) ||                                                                                                                                                                                                          
        ViewSlots.getViewXml(slotKey) ||                                                                                                                                                                                                                       
        ""                                                                                                                                                                                                                                                     
      );                                                                                                                                                                                                                                                       
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function slotFilled(slotKey) {                                                                                                                                                                                                                             
      return Boolean(getSlotXml(slotKey));                                                                                                                                                                                                                     
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
    // Groups - the five questions the tools are opened with                                                                                                                                                                                                   
    // ------------------------------------------------------------------                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    // A group is a top-level tab. They are ordered the way a session                                                                                                                                                                                          
    // runs: what is going on, what broke, what went over the wire, what                                                                                                                                                                                       
    // the screen is made of, what the system underneath looks like -                                                                                                                                                                                          
    // and last the cross-tab search, which is about all of them at once.                                                                                                                                                                                      
    const GROUPS = [                                                                                                                                                                                                                                           
      { key: "OVERVIEW", label: "Overview" },                                                                                                                                                                                                                  
      { key: "PROBLEMS", label: "Problems" },                                                                                                                                                                                                                  
      { key: "ROUNDTRIPS", label: "Roundtrips" },                                                                                                                                                                                                              
      { key: "VIEWDATA", label: "View & Data" },                                                                                                                                                                                                               
      { key: "SYSTEM", label: "System" },                                                                                                                                                                                                                      
      { key: "SEARCH", label: "Search" },                                                                                                                                                                                                                      
    ];                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    const DEFAULT_GROUP = "OVERVIEW";                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The View & Data group is TWO dimensions - which slot, and which                                                                                                                                                                                         
    // aspect of it - rather than the eight flat tabs it used to be                                                                                                                                                                                            
    // (VIEW / MODEL / POPUP / POPUP_MODEL / POPOVER / POPOVER_MODEL /                                                                                                                                                                                         
    // NEST1 / NEST2, most of them greyed out most of the time). The slot                                                                                                                                                                                      
    // is picked in one selector, the aspect in another, and only the                                                                                                                                                                                          
    // combinations that actually exist are offered.                                                                                                                                                                                                           
    const SLOTS = [                                                                                                                                                                                                                                            
      { key: "MAIN", label: "Main" },                                                                                                                                                                                                                          
      { key: "POPUP", label: "Popup" },                                                                                                                                                                                                                        
      { key: "POPOVER", label: "Popover" },                                                                                                                                                                                                                    
      { key: "NEST", label: "Nested 1" },                                                                                                                                                                                                                      
      { key: "NEST2", label: "Nested 2" },                                                                                                                                                                                                                     
    ];                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Aspect order inside a slot: the XML is what the backend sent, the                                                                                                                                                                                       
    // model is what fills it, the bindings are the check between the two.                                                                                                                                                                                     
    const ASPECTS = ["XML", "MODEL", "BINDINGS"];                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
    // The table                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    // Every entry:                                                                                                                                                                                                                                            
    //   key          stable identity (URL parameter, remembered last tab)                                                                                                                                                                                     
    //   group        the top-level tab it appears under                                                                                                                                                                                                       
    //   label        its name in the sub-view selector                                                                                                                                                                                                        
    //   kind         "json" | "xml" | "text" | "source" - how it renders                                                                                                                                                                                      
    //   produce()    the finished display string                                                                                                                                                                                                              
    //   rendered()   optional: the post-XML-templating variant (xml only)                                                                                                                                                                                     
    //   enabled()    optional: false hides the sub-view entirely                                                                                                                                                                                              
    //   slot/aspect  View & Data only - the two selector dimensions                                                                                                                                                                                           
    //   exportOrder  position in the export; absent = not exported                                                                                                                                                                                            
    //   exportTitle  section title; defaults to the upper-cased label                                                                                                                                                                                         
    //   searchable   false keeps a tab out of the cross-tab search                                                                                                                                                                                            
    const TABS = [                                                                                                                                                                                                                                             
      // -------- Overview --------                                                                                                                                                                                                                            
      {                                                                                                                                                                                                                                                        
        key: "OVERVIEW",                                                                                                                                                                                                                                       
        group: "OVERVIEW",                                                                                                                                                                                                                                     
        label: "Overview",                                                                                                                                                                                                                                     
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatOverview(),                                                                                                                                                                                                               
        // Not exported and not searched: every line of it is a summary of                                                                                                                                                                                     
        // a section the export already carries in full.                                                                                                                                                                                                       
        searchable: false,                                                                                                                                                                                                                                     
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      // -------- Problems --------                                                                                                                                                                                                                            
      {                                                                                                                                                                                                                                                        
        key: "ERROR",                                                                                                                                                                                                                                          
        group: "PROBLEMS",                                                                                                                                                                                                                                     
        label: "Error",                                                                                                                                                                                                                                        
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatError(),                                                                                                                                                                                                                  
        enabled: () => Boolean(AppState.state.lastError),                                                                                                                                                                                                      
        exportOrder: 20,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "LOG",                                                                                                                                                                                                                                            
        group: "PROBLEMS",                                                                                                                                                                                                                                     
        label: "Log",                                                                                                                                                                                                                                          
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatLog(),                                                                                                                                                                                                                    
        exportOrder: 30,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      // -------- Roundtrips --------                                                                                                                                                                                                                          
      {                                                                                                                                                                                                                                                        
        key: "HISTORY",                                                                                                                                                                                                                                        
        group: "ROUNDTRIPS",                                                                                                                                                                                                                                   
        label: "History",                                                                                                                                                                                                                                      
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Recorder.formatHistory(),                                                                                                                                                                                                               
        exportOrder: 40,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "REQUEST",                                                                                                                                                                                                                                        
        group: "ROUNDTRIPS",                                                                                                                                                                                                                                   
        label: "Request",                                                                                                                                                                                                                                      
        kind: "json",                                                                                                                                                                                                                                          
        produce: () => Format.toJson(AppState.state.oBody),                                                                                                                                                                                                    
        exportOrder: 80,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "PLAIN",                                                                                                                                                                                                                                          
        group: "ROUNDTRIPS",                                                                                                                                                                                                                                   
        label: "Response",                                                                                                                                                                                                                                     
        kind: "json",                                                                                                                                                                                                                                          
        produce: () => Format.toJson(AppState.state.responseData),                                                                                                                                                                                             
        exportOrder: 70,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "ACTIONS",                                                                                                                                                                                                                                        
        group: "ROUNDTRIPS",                                                                                                                                                                                                                                   
        label: "Actions",                                                                                                                                                                                                                                      
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatActions(),                                                                                                                                                                                                                
        exportOrder: 60,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "DIFF",                                                                                                                                                                                                                                           
        group: "ROUNDTRIPS",                                                                                                                                                                                                                                   
        label: "Model Diff",                                                                                                                                                                                                                                   
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Recorder.formatModelDiff(),                                                                                                                                                                                                             
        // Only in the export when it says something: without payload                                                                                                                                                                                          
        // recording it is a one-line "switch it on" notice, and a report                                                                                                                                                                                      
        // full of those reads as if the tools were broken.                                                                                                                                                                                                    
        exportOrder: 50,                                                                                                                                                                                                                                       
        inExport: () => Recorder.isRecordingPayloads(),                                                                                                                                                                                                        
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "VIEWDIFF",                                                                                                                                                                                                                                       
        group: "ROUNDTRIPS",                                                                                                                                                                                                                                   
        label: "View Diff",                                                                                                                                                                                                                                    
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Recorder.formatViewDiff(),                                                                                                                                                                                                              
        exportOrder: 51,                                                                                                                                                                                                                                       
        inExport: () => Recorder.isRecordingPayloads(),                                                                                                                                                                                                        
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      // -------- View & Data --------                                                                                                                                                                                                                         
      // MAIN                                                                                                                                                                                                                                                  
      {                                                                                                                                                                                                                                                        
        key: "VIEW",                                                                                                                                                                                                                                           
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "MAIN",                                                                                                                                                                                                                                          
        aspect: "XML",                                                                                                                                                                                                                                         
        label: "XML",                                                                                                                                                                                                                                          
        kind: "xml",                                                                                                                                                                                                                                           
        produce: () => Format.prettifyXml(getSlotXml("MAIN")),                                                                                                                                                                                                 
        rendered: () =>                                                                                                                                                                                                                                        
          Format.prettifyXml(getRenderedContent(ViewSlots.getView("MAIN"))),                                                                                                                                                                                   
        enabled: () => slotFilled("MAIN"),                                                                                                                                                                                                                     
        exportOrder: 90,                                                                                                                                                                                                                                       
        exportTitle: "VIEW",                                                                                                                                                                                                                                   
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "MODEL",                                                                                                                                                                                                                                          
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "MAIN",                                                                                                                                                                                                                                          
        aspect: "MODEL",                                                                                                                                                                                                                                       
        label: "Model",                                                                                                                                                                                                                                        
        kind: "json",                                                                                                                                                                                                                                          
        produce: () => Format.toJson(getModelJson(ViewSlots.getView("MAIN"))),                                                                                                                                                                                 
        enabled: () => hasModelData("MAIN"),                                                                                                                                                                                                                   
        exportOrder: 91,                                                                                                                                                                                                                                       
        exportTitle: "VIEW MODEL",                                                                                                                                                                                                                             
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "BINDINGS",                                                                                                                                                                                                                                       
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "MAIN",                                                                                                                                                                                                                                          
        aspect: "BINDINGS",                                                                                                                                                                                                                                    
        label: "Bindings",                                                                                                                                                                                                                                     
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatBindings("MAIN"),                                                                                                                                                                                                         
        enabled: () => hasModelData("MAIN"),                                                                                                                                                                                                                   
        exportOrder: 92,                                                                                                                                                                                                                                       
        exportTitle: "VIEW BINDINGS",                                                                                                                                                                                                                          
      },                                                                                                                                                                                                                                                       
      // POPUP                                                                                                                                                                                                                                                 
      {                                                                                                                                                                                                                                                        
        key: "POPUP",                                                                                                                                                                                                                                          
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "POPUP",                                                                                                                                                                                                                                         
        aspect: "XML",                                                                                                                                                                                                                                         
        label: "XML",                                                                                                                                                                                                                                          
        kind: "xml",                                                                                                                                                                                                                                           
        produce: () => Format.prettifyXml(getSlotXml("POPUP")),                                                                                                                                                                                                
        enabled: () => slotFilled("POPUP"),                                                                                                                                                                                                                    
        exportOrder: 100,                                                                                                                                                                                                                                      
        // Every slot has a sub-view called "XML", so the export title                                                                                                                                                                                         
        // has to name the slot - the default (the label) would produce                                                                                                                                                                                        
        // three sections called "XML".                                                                                                                                                                                                                        
        exportTitle: "POPUP",                                                                                                                                                                                                                                  
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "POPUP_MODEL",                                                                                                                                                                                                                                    
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "POPUP",                                                                                                                                                                                                                                         
        aspect: "MODEL",                                                                                                                                                                                                                                       
        label: "Model",                                                                                                                                                                                                                                        
        kind: "json",                                                                                                                                                                                                                                          
        produce: () => Format.toJson(getModelJson(ViewSlots.getView("POPUP"))),                                                                                                                                                                                
        enabled: () => hasModelData("POPUP"),                                                                                                                                                                                                                  
        exportOrder: 101,                                                                                                                                                                                                                                      
        exportTitle: "POPUP MODEL",                                                                                                                                                                                                                            
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "POPUP_BINDINGS",                                                                                                                                                                                                                                 
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "POPUP",                                                                                                                                                                                                                                         
        aspect: "BINDINGS",                                                                                                                                                                                                                                    
        label: "Bindings",                                                                                                                                                                                                                                     
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatBindings("POPUP"),                                                                                                                                                                                                        
        enabled: () => hasModelData("POPUP"),                                                                                                                                                                                                                  
        exportOrder: 102,                                                                                                                                                                                                                                      
        exportTitle: "POPUP BINDINGS",                                                                                                                                                                                                                         
      },                                                                                                                                                                                                                                                       
      // POPOVER                                                                                                                                                                                                                                               
      {                                                                                                                                                                                                                                                        
        key: "POPOVER",                                                                                                                                                                                                                                        
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "POPOVER",                                                                                                                                                                                                                                       
        aspect: "XML",                                                                                                                                                                                                                                         
        label: "XML",                                                                                                                                                                                                                                          
        kind: "xml",                                                                                                                                                                                                                                           
        produce: () => Format.prettifyXml(getSlotXml("POPOVER")),                                                                                                                                                                                              
        enabled: () => slotFilled("POPOVER"),                                                                                                                                                                                                                  
        exportOrder: 110,                                                                                                                                                                                                                                      
        exportTitle: "POPOVER",                                                                                                                                                                                                                                
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "POPOVER_MODEL",                                                                                                                                                                                                                                  
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "POPOVER",                                                                                                                                                                                                                                       
        aspect: "MODEL",                                                                                                                                                                                                                                       
        label: "Model",                                                                                                                                                                                                                                        
        kind: "json",                                                                                                                                                                                                                                          
        produce: () =>                                                                                                                                                                                                                                         
          Format.toJson(getModelJson(ViewSlots.getView("POPOVER"))),                                                                                                                                                                                           
        enabled: () => hasModelData("POPOVER"),                                                                                                                                                                                                                
        exportOrder: 111,                                                                                                                                                                                                                                      
        exportTitle: "POPOVER MODEL",                                                                                                                                                                                                                          
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "POPOVER_BINDINGS",                                                                                                                                                                                                                               
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "POPOVER",                                                                                                                                                                                                                                       
        aspect: "BINDINGS",                                                                                                                                                                                                                                    
        label: "Bindings",                                                                                                                                                                                                                                     
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatBindings("POPOVER"),                                                                                                                                                                                                      
        enabled: () => hasModelData("POPOVER"),                                                                                                                                                                                                                
        exportOrder: 112,                                                                                                                                                                                                                                      
        exportTitle: "POPOVER BINDINGS",                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      // The nested slots carry no model of their own - they inherit                                                                                                                                                                                           
      // MAIN's by UI5 propagation, so only the XML is an aspect here.                                                                                                                                                                                         
      {                                                                                                                                                                                                                                                        
        key: "NEST1",                                                                                                                                                                                                                                          
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "NEST",                                                                                                                                                                                                                                          
        aspect: "XML",                                                                                                                                                                                                                                         
        label: "XML",                                                                                                                                                                                                                                          
        kind: "xml",                                                                                                                                                                                                                                           
        produce: () => Format.prettifyXml(getSlotXml("NEST")),                                                                                                                                                                                                 
        rendered: () =>                                                                                                                                                                                                                                        
          Format.prettifyXml(getRenderedContent(ViewSlots.getView("NEST"))),                                                                                                                                                                                   
        enabled: () => slotFilled("NEST"),                                                                                                                                                                                                                     
        exportOrder: 120,                                                                                                                                                                                                                                      
        exportTitle: "NEST1",                                                                                                                                                                                                                                  
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "NEST2",                                                                                                                                                                                                                                          
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        slot: "NEST2",                                                                                                                                                                                                                                         
        aspect: "XML",                                                                                                                                                                                                                                         
        label: "XML",                                                                                                                                                                                                                                          
        kind: "xml",                                                                                                                                                                                                                                           
        produce: () => Format.prettifyXml(getSlotXml("NEST2")),                                                                                                                                                                                                
        rendered: () =>                                                                                                                                                                                                                                        
          Format.prettifyXml(getRenderedContent(ViewSlots.getView("NEST2"))),                                                                                                                                                                                  
        enabled: () => slotFilled("NEST2"),                                                                                                                                                                                                                    
        exportOrder: 121,                                                                                                                                                                                                                                      
        exportTitle: "NEST2",                                                                                                                                                                                                                                  
      },                                                                                                                                                                                                                                                       
      // The picked control belongs to this group - going from a control                                                                                                                                                                                       
      // on screen to the attribute that feeds it is the same question                                                                                                                                                                                         
      // the bindings answer from the other end - but it is the one entry                                                                                                                                                                                      
      // here that is NOT about a slot, so it hides the slot selector.                                                                                                                                                                                         
      {                                                                                                                                                                                                                                                        
        key: "PICK",                                                                                                                                                                                                                                           
        group: "VIEWDATA",                                                                                                                                                                                                                                     
        aspect: "PICK",                                                                                                                                                                                                                                        
        label: "Picked Control",                                                                                                                                                                                                                               
        kind: "text",                                                                                                                                                                                                                                          
        produce: () =>                                                                                                                                                                                                                                         
          Picker.lastReport() ||                                                                                                                                                                                                                               
          'No control picked yet - press "Pick Control", then click any' +                                                                                                                                                                                     
            " control in the app.",                                                                                                                                                                                                                            
        searchable: true,                                                                                                                                                                                                                                      
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      // -------- Search --------                                                                                                                                                                                                                              
      // The cross-tab search as a tab of its own. It used to be a                                                                                                                                                                                             
      // permanent field in the dialog's sub-header, and the result                                                                                                                                                                                            
      // silently replaced whatever tab was open underneath - which read                                                                                                                                                                                       
      // as the tab's own content having changed. As a tab, entering and                                                                                                                                                                                       
      // leaving the result is the same navigation as everywhere else.                                                                                                                                                                                         
      {                                                                                                                                                                                                                                                        
        key: "SEARCH",                                                                                                                                                                                                                                         
        group: "SEARCH",                                                                                                                                                                                                                                       
        label: "Search",                                                                                                                                                                                                                                       
        // Rendered by the dialog, not by produce(): the result depends                                                                                                                                                                                        
        // on the entered term, which lives in the dialog model.                                                                                                                                                                                               
        kind: "search",                                                                                                                                                                                                                                        
        produce: () => "",                                                                                                                                                                                                                                     
        // The search must not scan its own result.                                                                                                                                                                                                            
        searchable: false,                                                                                                                                                                                                                                     
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      // -------- System --------                                                                                                                                                                                                                              
      {                                                                                                                                                                                                                                                        
        key: "ENV",                                                                                                                                                                                                                                            
        group: "SYSTEM",                                                                                                                                                                                                                                       
        label: "Environment",                                                                                                                                                                                                                                  
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatEnvironment(),                                                                                                                                                                                                            
        // First section of the export on purpose: versions, UI5                                                                                                                                                                                               
        // distribution, launchpad and device are what a reader of a                                                                                                                                                                                           
        // shared report needs before anything else, and asking for them                                                                                                                                                                                       
        // is the standard first reply to a bug report.                                                                                                                                                                                                        
        exportOrder: 10,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "REGISTRY",                                                                                                                                                                                                                                       
        group: "SYSTEM",                                                                                                                                                                                                                                       
        label: "Registry",                                                                                                                                                                                                                                     
        kind: "text",                                                                                                                                                                                                                                          
        produce: () => Inspect.formatRegistry(),                                                                                                                                                                                                               
        exportOrder: 61,                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      {                                                                                                                                                                                                                                                        
        key: "SOURCE",                                                                                                                                                                                                                                         
        group: "SYSTEM",                                                                                                                                                                                                                                       
        label: "ABAP Source",                                                                                                                                                                                                                                  
        // Not the code editor: the ADT endpoint renders the class itself,                                                                                                                                                                                     
        // framed by the dialog (see devtools/AbapSource.js).                                                                                                                                                                                                  
        kind: "source",                                                                                                                                                                                                                                        
        produce: () => "",                                                                                                                                                                                                                                     
        // The class source travels in the export, but it is fetched                                                                                                                                                                                           
        // asynchronously and passed in - Report.js places it, not this.                                                                                                                                                                                       
        searchable: false,                                                                                                                                                                                                                                     
      },                                                                                                                                                                                                                                                       
    ];                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    const byKey = new Map(TABS.map((tab) => [tab.key, tab]));                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
    // Lookup                                                                                                                                                                                                                                                  
    // ------------------------------------------------------------------                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    function get(tabKey) {                                                                                                                                                                                                                                     
      return byKey.get(tabKey);                                                                                                                                                                                                                                
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function isKnown(tabKey) {                                                                                                                                                                                                                                 
      return Boolean(tabKey && byKey.has(tabKey));                                                                                                                                                                                                             
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function isEnabled(tab) {                                                                                                                                                                                                                                  
      if (!tab) return false;                                                                                                                                                                                                                                  
      try {                                                                                                                                                                                                                                                    
        return tab.enabled ? Boolean(tab.enabled()) : true;                                                                                                                                                                                                    
      } catch {                                                                                                                                                                                                                                                
        // A source that throws while deciding whether it has anything to                                                                                                                                                                                      
        // show must not take the whole tab strip with it.                                                                                                                                                                                                     
        return false;                                                                                                                                                                                                                                          
      }                                                                                                                                                                                                                                                        
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function groupOf(tabKey) {                                                                                                                                                                                                                                 
      return get(tabKey)?.group || DEFAULT_GROUP;                                                                                                                                                                                                              
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The tabs of a group that have something to show right now, in                                                                                                                                                                                           
    // table order.                                                                                                                                                                                                                                            
    function enabledTabs(groupKey) {                                                                                                                                                                                                                           
      return TABS.filter((tab) => tab.group === groupKey && isEnabled(tab));                                                                                                                                                                                   
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The tab a group opens on when it is selected without a specific                                                                                                                                                                                         
    // sub-view - the first one that is enabled.                                                                                                                                                                                                               
    function firstTabOf(groupKey) {                                                                                                                                                                                                                            
      const [first] = enabledTabs(groupKey);                                                                                                                                                                                                                   
      return first?.key || "";                                                                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The slots that hold something, in SLOTS order. Drives the slot                                                                                                                                                                                          
    // selector of View & Data; empty slots are not offered at all.                                                                                                                                                                                            
    function enabledSlots() {                                                                                                                                                                                                                                  
      const available = new Set(                                                                                                                                                                                                                               
        enabledTabs("VIEWDATA")                                                                                                                                                                                                                                
          .filter((tab) => tab.slot)                                                                                                                                                                                                                           
          .map((tab) => tab.slot),                                                                                                                                                                                                                             
      );                                                                                                                                                                                                                                                       
      return SLOTS.filter((slot) => available.has(slot.key));                                                                                                                                                                                                  
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The aspects available for one slot, in ASPECTS order.                                                                                                                                                                                                   
    function aspectsOfSlot(slotKey) {                                                                                                                                                                                                                          
      return enabledTabs("VIEWDATA")                                                                                                                                                                                                                           
        .filter((tab) => tab.slot === slotKey)                                                                                                                                                                                                                 
        .sort((a, b) => ASPECTS.indexOf(a.aspect) - ASPECTS.indexOf(b.aspect));                                                                                                                                                                                
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The tab for a (slot, aspect) pair, falling back to the slot's                                                                                                                                                                                           
    // first available aspect - switching from Popup/Model to a slot that                                                                                                                                                                                      
    // has no model must land somewhere rather than nowhere.                                                                                                                                                                                                   
    function tabFor(slotKey, aspect) {                                                                                                                                                                                                                         
      const aspects = aspectsOfSlot(slotKey);                                                                                                                                                                                                                  
      const exact = aspects.find((tab) => tab.aspect === aspect);                                                                                                                                                                                              
      return (exact || aspects[0])?.key || "";                                                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
    // Content                                                                                                                                                                                                                                                 
    // ------------------------------------------------------------------                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    // The finished display string of a tab. Guarded: one broken source                                                                                                                                                                                        
    // may not blank the dialog, and the message says which tab broke.                                                                                                                                                                                         
    function render(tabKey) {                                                                                                                                                                                                                                  
      const tab = get(tabKey);                                                                                                                                                                                                                                 
      if (!tab) return "";                                                                                                                                                                                                                                     
      try {                                                                                                                                                                                                                                                    
        return tab.produce() ?? "";                                                                                                                                                                                                                            
      } catch (e) {                                                                                                                                                                                                                                            
        return `(${tab.label} could not be rendered: ${e?.message || e})`;                                                                                                                                                                                     
      }                                                                                                                                                                                                                                                        
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // The post-XML-templating variant, for the tabs that have one.                                                                                                                                                                                            
    function renderTemplated(tabKey) {                                                                                                                                                                                                                         
      const tab = get(tabKey);                                                                                                                                                                                                                                 
      if (!tab?.rendered) return "";                                                                                                                                                                                                                           
      try {                                                                                                                                                                                                                                                    
        return tab.rendered() || "";                                                                                                                                                                                                                           
      } catch {                                                                                                                                                                                                                                                
        return "";                                                                                                                                                                                                                                             
      }                                                                                                                                                                                                                                                        
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // Every tab the cross-tab search looks at. A tab that is disabled                                                                                                                                                                                         
    // right now holds nothing, so searching it would only cost time.                                                                                                                                                                                          
    function searchableTabs() {                                                                                                                                                                                                                                
      return TABS.filter((tab) => tab.searchable !== false && isEnabled(tab));                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // Every tab the export carries, in exportOrder. `inExport` is the                                                                                                                                                                                         
    // second gate, for content that exists but says nothing worth                                                                                                                                                                                             
    // shipping (a model diff without payload recording).                                                                                                                                                                                                      
    function exportTabs() {                                                                                                                                                                                                                                    
      return TABS.filter((tab) => {                                                                                                                                                                                                                            
        if (tab.exportOrder === undefined) return false;                                                                                                                                                                                                       
        if (!isEnabled(tab)) return false;                                                                                                                                                                                                                     
        try {                                                                                                                                                                                                                                                  
          return tab.inExport ? Boolean(tab.inExport()) : true;                                                                                                                                                                                                
        } catch {                                                                                                                                                                                                                                              
          return false;                                                                                                                                                                                                                                        
        }                                                                                                                                                                                                                                                      
      }).sort((a, b) => a.exportOrder - b.exportOrder);                                                                                                                                                                                                        
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    function exportTitle(tab) {                                                                                                                                                                                                                                
      return tab.exportTitle || tab.label.toUpperCase();                                                                                                                                                                                                       
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // ------------------------------------------------------------------                                                                                                                                                                                      
    // Cross-tab search                                                                                                                                                                                                                                        
    // ------------------------------------------------------------------                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    // Hits reported per tab. A term that matches a whole model would                                                                                                                                                                                          
    // otherwise bury the tabs that matched it once.                                                                                                                                                                                                           
    const MAX_HITS_PER_TAB = 20;                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
    // The name a hit is reported under. A View & Data tab needs its slot                                                                                                                                                                                      
    // to be identifiable at all - three slots have a sub-view called                                                                                                                                                                                          
    // "XML", and "[XML] 4 hits" would say nothing about where to look.                                                                                                                                                                                        
    function searchLabel(tab) {                                                                                                                                                                                                                                
      const group = GROUPS.find((entry) => entry.key === tab.group);                                                                                                                                                                                           
      const slot = SLOTS.find((entry) => entry.key === tab.slot);                                                                                                                                                                                              
      const parts = [group?.label || tab.group];                                                                                                                                                                                                               
      if (slot) parts.push(slot.label);                                                                                                                                                                                                                        
      parts.push(tab.label);                                                                                                                                                                                                                                   
      return parts.join(" > ");                                                                                                                                                                                                                                
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    // Search every tab at once and report which of them contain the term.                                                                                                                                                                                     
    // With more than twenty views, "where does CUSTOMER appear?" is a                                                                                                                                                                                         
    // question the dialog could not answer at all - the developer had to                                                                                                                                                                                      
    // open each one and use the editor's own find.                                                                                                                                                                                                            
    //                                                                                                                                                                                                                                                         
    // Tabs.render is guarded per tab, so one throwing source can never                                                                                                                                                                                        
    // blank the whole result.                                                                                                                                                                                                                                 
    function search(term) {                                                                                                                                                                                                                                    
      const needle = String(term || "").toLowerCase();                                                                                                                                                                                                         
      if (!needle) return "(enter a search term)";                                                                                                                                                                                                             
      const sections = [];                                                                                                                                                                                                                                     
      let totalHits = 0;                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      for (const tab of searchableTabs()) {                                                                                                                                                                                                                    
        const text = render(tab.key);                                                                                                                                                                                                                          
        if (!text) continue;                                                                                                                                                                                                                                   
        const lines = String(text).split("\n");                                                                                                                                                                                                                
        const hits = [];                                                                                                                                                                                                                                       
        for (let i = 0; i < lines.length; i += 1) {                                                                                                                                                                                                            
          if (!lines[i].toLowerCase().includes(needle)) continue;                                                                                                                                                                                              
          hits.push(`    ${String(i + 1).padStart(5)}: ${lines[i].trim()}`);                                                                                                                                                                                   
          if (hits.length >= MAX_HITS_PER_TAB) break;                                                                                                                                                                                                          
        }                                                                                                                                                                                                                                                      
        if (!hits.length) continue;                                                                                                                                                                                                                            
        totalHits += hits.length;                                                                                                                                                                                                                              
        sections.push(                                                                                                                                                                                                                                         
          `  [${searchLabel(tab)}]  ${hits.length}` +                                                                                                                                                                                                          
            `${hits.length >= MAX_HITS_PER_TAB ? "+" : ""} hit(s)`,                                                                                                                                                                                            
        );                                                                                                                                                                                                                                                     
        sections.push(...hits);                                                                                                                                                                                                                                
        sections.push("");                                                                                                                                                                                                                                     
      }                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
      const head = [                                                                                                                                                                                                                                           
        `Search for "${term}" across every tab`,                                                                                                                                                                                                               
        "",                                                                                                                                                                                                                                                    
        totalHits                                                                                                                                                                                                                                              
          ? `${totalHits} hit(s) - the tab is named in brackets.`                                                                                                                                                                                              
          : "(no hit in any tab)",                                                                                                                                                                                                                             
        "",                                                                                                                                                                                                                                                    
      ];                                                                                                                                                                                                                                                       
      return head.concat(sections).join("\n");                                                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    return {                                                                                                                                                                                                                                                   
      GROUPS,                                                                                                                                                                                                                                                  
      SLOTS,                                                                                                                                                                                                                                                   
      ASPECTS,                                                                                                                                                                                                                                                 
      DEFAULT_GROUP,                                                                                                                                                                                                                                           
      get,                                                                                                                                                                                                                                                     
      isKnown,                                                                                                                                                                                                                                                 
      isEnabled,                                                                                                                                                                                                                                               
      groupOf,                                                                                                                                                                                                                                                 
      enabledTabs,                                                                                                                                                                                                                                             
      firstTabOf,                                                                                                                                                                                                                                              
      enabledSlots,                                                                                                                                                                                                                                            
      aspectsOfSlot,                                                                                                                                                                                                                                           
      tabFor,                                                                                                                                                                                                                                                  
      render,                                                                                                                                                                                                                                                  
      renderTemplated,                                                                                                                                                                                                                                         
      search,                                                                                                                                                                                                                                                  
      searchableTabs,                                                                                                                                                                                                                                          
      exportTabs,                                                                                                                                                                                                                                              
      exportTitle,                                                                                                                                                                                                                                             
      // exposed for the unit specs                                                                                                                                                                                                                            
      _internals: { TABS, getSlotXml, hasModelData, searchLabel },                                                                                                                                                                                             
    };                                                                                                                                                                                                                                                         
  },                                                                                                                                                                                                                                                           
);                                                                                                                                                                                                                                                             